{
  "root_causes": [
    {
      "service": "ts-station-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration/1e6, 0.95) p95_ms FROM abnormal_traces WHERE service_name='ts-station-service' AND span_name='SELECT station' GROUP BY 1,2", "claim": "Station's 'SELECT station' DB spans have p95 around 30,000 ms during the incident."},
        {"kind": "log", "sql": "SELECT level, message, count(*) c FROM abnormal_logs WHERE service_name='ts-station-service' AND level IN ('ERROR','SEVERE','WARN') GROUP BY 1,2 ORDER BY c DESC", "claim": "Station logs Hikari 'Connection is not available, request timed out after 30000ms' and communication link failures."},
        {"kind": "metric", "sql": "SELECT metric, attr_k8s_pod_name, count(*) n, max(value) max_v FROM abnormal_metrics_sum WHERE attr_k8s_pod_name LIKE 'ts-station-service%' AND metric LIKE 'db.client.connections%' GROUP BY 1,2", "claim": "Station's DB connection pool shows pending requests and timeouts, indicating pool exhaustion."},
        {"kind": "metric", "sql": "SELECT metric, attr_k8s_pod_name, avg(value) avg_v, max(value) max_v FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'ts-station-service%' AND metric IN ('container.cpu.usage','container.memory.working_set') GROUP BY 1,2", "claim": "Station pod CPU and memory stay low, so the slowdown is not container saturation."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-station-service", "to": "ts-basic-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, sum(CASE WHEN c.attr_http_response_status_code>=500 THEN 1 ELSE 0 END) callee_5xx, approx_quantile(c.duration/1e6,0.5) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.service_name<>c.service_name AND c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND c.service_name='ts-station-service' GROUP BY 1,2", "claim": "Basic's client calls to station return 5xx after about 30 s, 18 of 21 server spans failing."}]},
    {"from": "ts-basic-service", "to": "ts-travel-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, sum(CASE WHEN c.attr_http_response_status_code>=500 THEN 1 ELSE 0 END) callee_5xx, approx_quantile(c.duration/1e6,0.5) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.service_name<>c.service_name AND c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND c.service_name='ts-basic-service' GROUP BY 1,2", "claim": "Travel's calls to basic take about 60 s and return 5xx (8 of 10), so travel inherits the stall."}]},
    {"from": "ts-travel-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, sum(CASE WHEN c.attr_http_response_status_code>=500 THEN 1 ELSE 0 END) callee_5xx, approx_quantile(c.duration/1e6,0.5) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.service_name<>c.service_name AND c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-route-plan-service' AND c.service_name='ts-travel-service' GROUP BY 1,2", "claim": "Route-plan's calls to travel fail with 5xx (3 of 6) after roughly 37 s."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, sum(CASE WHEN c.attr_http_response_status_code>=500 THEN 1 ELSE 0 END) callee_5xx, approx_quantile(c.duration/1e6,0.5) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.service_name<>c.service_name AND c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND c.service_name='ts-route-plan-service' GROUP BY 1,2", "claim": "Travel-plan's calls to route-plan take about 60 s and return 5xx (3 of 5)."}]},
    {"from": "ts-travel-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT s.service_name, s.span_name, count(*) n, sum(CASE WHEN s.attr_http_response_status_code>=500 THEN 1 ELSE 0 END) http5xx, approx_quantile(s.duration/1e6,0.95) p95_ms FROM abnormal_traces s WHERE s.service_name='ts-travel-service' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "Travel's server spans reach p95 near 60 s with 5xx responses, which ui-dashboard's requests to travel inherit."}]},
    {"from": "ts-travel2-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT s.service_name, s.span_name, count(*) n, sum(CASE WHEN s.attr_http_response_status_code>=500 THEN 1 ELSE 0 END) http5xx, approx_quantile(s.duration/1e6,0.95) p95_ms FROM abnormal_traces s WHERE s.service_name='ts-travel2-service' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "Travel2's server spans show multi-second to 60 s latency and some 5xx, inherited from its calls to basic."}]}
  ]
}
